create table xxventuri.eba_sales_product_families (
    id                number,
    product_family    varchar2(100 byte),
    description       varchar2(4000 byte),
    created           timestamp(6) with local time zone,
    created_by        varchar2(255 byte),
    updated           timestamp(6) with local time zone,
    updated_by        varchar2(255 byte),
    group_code        varchar2(100 byte),
    margin_percentage number,
    status            varchar2(10 byte),
    manager_id        number,
    manager_limit     number,
    sales_team        varchar2(500 byte),
    product_sku       varchar2(255 byte)
);

alter table xxventuri.eba_sales_product_families
    add constraint eba_sales_product_families_pk primary key ( id )
        using index enable;


